begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(14);
grant usage on schema extensions to mcp_import;
grant execute on all functions in schema extensions to mcp_import;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values
('18500000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp185@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18500000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18500000-0000-0000-0000-000000000002','18500000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18500000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18500000-0000-0000-0000-000000000004','18500000-0000-0000-0000-000000000001','18500000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18500000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18500000-0000-0000-0000-000000000005','18500000-0000-0000-0000-000000000001','18500000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('18500000-0000-0000-0000-000000000006','18500000-0000-0000-0000-000000000002','Synthetic client');
insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18500000-0000-0000-0000-000000000007','18500000-0000-0000-0000-000000000002','18500000-0000-0000-0000-000000000006','2026-07-01 00:00+09','2026-07-01 02:00+09','published');
insert into public.reports(id,client_id,helper_id,start_at,end_at,service_date,status) values ('18500000-0000-0000-0000-000000000008','18500000-0000-0000-0000-000000000006','18500000-0000-0000-0000-000000000001','2026-07-01 00:00+09','2026-07-01 02:00+09','2026-07-01','pending');
insert into public.report_values(report_id,data) values ('18500000-0000-0000-0000-000000000008','{"service_time":1,"travel_time":0.5,"_helpers":["A","B"],"note":"Synthetic private note"}');
insert into private.mcp_record_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18500000-0000-0000-0000-000000000002',true,'{}','18500000-0000-0000-0000-000000000001',now());
insert into private.mcp_shift_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18500000-0000-0000-0000-000000000002',true,'{}','18500000-0000-0000-0000-000000000001',now());
set local role mcp_import;
select set_config('request.jwt.claims','{"sub":"18500000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18500000-0000-0000-0000-000000000003","session_id":"18500000-0000-0000-0000-000000000005"}',true);
select throws_ok($$select public.get_mcp_kpi_source('18500000-0000-0000-0000-000000000002','2026-07')$$,'42501','mcp_kpi_unavailable','KPI defaults off');
reset role;
insert into private.mcp_kpi_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18500000-0000-0000-0000-000000000002',true,'{}','18500000-0000-0000-0000-000000000001',now());
set local role mcp_import;
select is(jsonb_array_length(public.get_mcp_kpi_source('18500000-0000-0000-0000-000000000002','2026-07')->'shifts'),1,'authorized shift included');
select is(public.get_mcp_kpi_source('18500000-0000-0000-0000-000000000002','2026-07')->'reports'->0->>'staff_count','2','helper count preserved');
select is(public.get_mcp_kpi_source('18500000-0000-0000-0000-000000000002','2026-07')->'reports'->0->>'service_time','1','service time retained');
select ok(public.get_mcp_kpi_source('18500000-0000-0000-0000-000000000002','2026-07')::text !~ 'Synthetic|18500000|_helpers|note','no identifiers, names, or note in projection');
select throws_ok($$select public.get_mcp_kpi_source('18500000-0000-0000-0000-000000000099','2026-07')$$,'42501','mcp_record_read_unavailable','other organization denied');
select throws_ok($$select public.get_mcp_kpi_source('18500000-0000-0000-0000-000000000002','2026-13')$$,'22023','invalid_kpi_month','invalid month rejected');
reset role;
savepoint excessive_shifts;
insert into public.shifts(organization_id,client_id,start_at,end_at,status)
select '18500000-0000-0000-0000-000000000002','18500000-0000-0000-0000-000000000006','2026-07-02 00:00+09','2026-07-02 01:00+09','published' from generate_series(1,1000);
set local role mcp_import;
select throws_ok($$select public.get_mcp_kpi_source('18500000-0000-0000-0000-000000000002','2026-07')$$,'54000','mcp_kpi_limit','over 1000 rows rejected rather than truncated');
reset role;
rollback to savepoint excessive_shifts;
select ok(not has_function_privilege('mcp_import','private.get_mcp_kpi_source(uuid,text)','execute'),'MCP cannot bypass the row limit');
update private.mcp_shift_read_controls set enabled=false where organization_id='18500000-0000-0000-0000-000000000002';
set local role mcp_import;
select throws_ok($$select public.get_mcp_kpi_source('18500000-0000-0000-0000-000000000002','2026-07')$$,'42501','mcp_shift_read_unavailable','shift switch enforced');
reset role;
select ok(not has_function_privilege('authenticated','public.get_mcp_kpi_source(uuid,text)','execute'),'browser cannot execute MCP RPC');
select ok(not has_table_privilege('mcp_import','private.mcp_kpi_controls','select,insert,update,delete'),'MCP cannot access control table');
update private.mcp_shift_read_controls set enabled=true where organization_id='18500000-0000-0000-0000-000000000002';
update public.organization_members set role='member' where organization_id='18500000-0000-0000-0000-000000000002' and user_id='18500000-0000-0000-0000-000000000001';
insert into public.organization_roles(id,organization_id,name,permissions) values ('18500000-0000-0000-0000-000000000009','18500000-0000-0000-0000-000000000002','Synthetic','{"records":{"view":"assigned"},"shifts":{"view":"all"},"management":{"reports":true}}');
insert into public.organization_member_roles(organization_id,user_id,role_id) values ('18500000-0000-0000-0000-000000000002','18500000-0000-0000-0000-000000000001','18500000-0000-0000-0000-000000000009');
set local role mcp_import;
select throws_ok($$select public.get_mcp_kpi_source('18500000-0000-0000-0000-000000000002','2026-07')$$,'42501','mcp_kpi_unavailable','partial record scope rejected');
reset role;
update public.organization_roles set permissions='{"records":{"view":"all"},"shifts":{"view":"all"},"management":{"reports":false}}' where id='18500000-0000-0000-0000-000000000009';
set local role mcp_import;
select throws_ok($$select public.get_mcp_kpi_source('18500000-0000-0000-0000-000000000002','2026-07')$$,'42501','mcp_kpi_unavailable','report management required');
reset role;
select * from finish();
rollback;
